<?php if (!defined('BASEPATH')) exit('No direct script access allowed');class macceptancelevel extends CI_Controller {    public function __construct() {        parent::__construct();        fnIfCheckUserLoggedIn();        $this->load->model(CNFCOMPANY . "macceptancelevelmodel");        $this->load->helper('xssclean');        $this->limit = LIMITPERPAGE;    }    public function addedit() {        $ArrData = array('ArrBasicInfo' => array(), 'VarId' => '', 'VarNew' => 0);        $VarHashId = $this->uri->segment(4);        $ArrData['Edit'] = $this->uri->segment(5);        if ($VarHashId <> '') {            $VarId = base64_decode(urldecode($VarHashId));            $ArrResults = $this->macceptancelevelmodel->fnGetAcceptlevelInfo('', '', $VarId);            $ArrData['ArrBasicInfo'] = $ArrResults[0];            $ArrData['VarId'] = $ArrResults[0]['id'];        } else {            $ArrData['VarNew'] = 1;        }        $this->load->view(CNFCOMPANY . 'addeditacceptlevel', $ArrData);    }    public function updateInfo() {        $ArrResult = [];        $VarUserInfo = fnGetUserLoggedInfo(1);        $VarCompanyId = $VarUserInfo['companyid'];        $VarAcceptlevel = xssclean($this->input->post('al'));        $VarStatus = xssclean($this->input->post('s'));        $VarId = xssclean($this->input->post('id'));        if ($VarAcceptlevel <> '') {            $ArrUpdateData = array('id' => $VarId, 'companyid' => $VarCompanyId, 'acceptablelevel' => $VarAcceptlevel, 'status' => $VarStatus, 'updatedby' => $VarUserInfo['id'], 'dateupdated' => date('Y-m-d H:i:s'));            if ($VarId == '' || $VarId == 0) {                $ArrUpdateData['datecreated'] = date('Y-m-d H:i:s');            }            $ArrResult = $this->macceptancelevelmodel->saveAcceptlevelInfo($ArrUpdateData);        } else {            $ArrResult['errcode'] = -1;            $ArrResult['msg'] = 'Invalid Input!';        }        echo json_encode($ArrResult);    }    public function manage() {        $VarFrom = xssclean($this->input->post('rfrom'));        $VarAcceptanceLevel = trim(xssclean($this->input->post('al')));        $VarStatus = xssclean($this->input->post('s'));        $clickedColumnId = xssclean($this->input->post('columnId'));        $newsortorder = xssclean($this->input->post('sortorder'));        $VarAfilter = xssclean($this->input->post('afilter'));        $ArrDbCols = array('acceptablelevel', 'status', 'contactname', 'dateupdated');        if ($VarFrom == 1) {            $VarURLSegment = 4;            $this->load->library('pagination');            $config['base_url'] = base_url() . CNFCOMPANY . 'macceptancelevel/manage';            $config['total_rows'] = $this->macceptancelevelmodel->fnCountAcceptlevel($VarAcceptanceLevel, $VarStatus, $VarAfilter);            $config['per_page'] = $this->limit;            $config['uri_segment'] = $VarURLSegment;            $offset = $this->uri->segment($VarURLSegment);            $this->pagination->initialize($config);            $sortby = "dateupdated";            $sortorder = "desc";            if ($clickedColumnId <> '' && $newsortorder <> '') {                if (array_key_exists($clickedColumnId, $ArrDbCols)) {                    $sortby = $ArrDbCols[$clickedColumnId];                }                $sortorder = $newsortorder;            }            $ArrFabricTypeList = $this->macceptancelevelmodel->fnListAcceptlevel($VarAcceptanceLevel, $VarStatus, $this->limit, $offset, $sortby, $sortorder, $VarAfilter)->result();            $data['pagination'] = $this->pagination->create_linkswithajax('Acceptancelevel');            $i = 0;            $ArrFnlList = array();            $ArrStatus = unserialize(ARRSTATUS);            foreach ($ArrFabricTypeList as $ObjFabric) {                $ArrFnlList[$i]['id'] = $ObjFabric->id;                $ArrFnlList[$i]['al'] = $ObjFabric->acceptablelevel;                $ArrFnlList[$i]['ub'] = !empty($ObjFabric->contactname)?$ObjFabric->contactname:"";                $ArrFnlList[$i]['s'] = $ArrStatus[$ObjFabric->status];                // $ArrFnlList[$i]['du'] = date('d-m-Y H:i:s', strtotime($ObjFabric->dateupdated));                 $ArrFnlList[$i]['du'] = date('d-m-Y H:i A', strtotime($ObjFabric->dateupdated));                $i = $i + 1;            }            echo json_encode(array('errcode' => 1, 'cn' => $config['total_rows'], 'ct' => $i, 're' => $ArrFnlList, 'pa' => base64_encode($data['pagination'])));            unset($ArrFnlList);            die;        } else {            $this->load->view(CNFCOMPANY . 'manageacceptlevel', array('ArrStatus' => unserialize(ARRSTATUS)));        }    }    function changeStatus() {        $VarRfrom = xssclean($this->input->post('rfrom'));        if ($VarRfrom == 1) {            $VarActDeactOption = xssclean($this->input->post('actdeactFabType'));            $VarCid = xssclean($this->input->post('cid'));            if ($VarActDeactOption <> '' && $VarCid <> '') {                $this->macceptancelevelmodel->changeStatus($VarCid, $VarActDeactOption);            }            echo json_encode(array('errcode' => 1));            die;        }    }}